function detectInitialCurrency(){const stored=(()=>{try{return localStorage.getItem(STORAGE_KEY_CURRENCY);}catch(_){return null;}})();if(stored&&SUPPORTED_CURRENCIES.includes(stored))return stored;const browser=(navigator.language||'en').toLowerCase();if(browser==='en-us'||browser.startsWith('en-us'))return'usd';return'eur';}
