function detectInitialTheme(){const stored=(()=>{try{return localStorage.getItem(STORAGE_KEY_THEME);}catch(_){return null;}})();if(stored&&SUPPORTED_THEMES.includes(stored))return stored;if(window.matchMedia&&window.matchMedia('(prefers-color-scheme: light)').matches)return'light';return'dark';}
